    const { width } = useWindowDimensions(); const mobile = width < 760; const compact = width < 1100;
    const [data, setData] = useState<any>(seed); const [loading, setLoading] = useState(true); const [online, setOnline] = useState(true); const [page, setPage] = useState('Overview'); const [role] = useState('Relationship owner'); const [query, setQuery] = useState(''); const [filter, setFilter] = useState('All customers'); const [sentimentFilter, setSentimentFilter] = useState('All sentiments'); const [unit, setUnit] = useState('All business units'); const [period, setPeriod] = useState('This month'); const [customer, setCustomer] = useState<string | null>(null); const [tab, setTab] = useState('Timeline'); const [modal, setModal] = useState<any>(null); const [toast, setToast] = useState(''); const [menu, setMenu] = useState(false); const [actionFilter, setActionFilter] = useState('All actions'); const [read, setRead] = useState<string[]>([]); const [searchFunction, setSearchFunction] = useState('All functions'); const [searchLeader, setSearchLeader] = useState('All leaders'); const [searchCategory, setSearchCategory] = useState('All categories'); const [searchDate, setSearchDate] = useState(''); const [searchStatus, setSearchStatus] = useState('All statuses');
    useEffect(() => { refresh(role) }, [role]);
    useEffect(() => { if (toast) { let t = setTimeout(() => setToast(''), 4200); return () => clearTimeout(t) } }, [toast]);
