    function notify(s: string) { setToast(s) }
    async function save(path: string, body: any) { const d = await api(path, 'POST', body, role); await refresh(); return d; }
    const go = (p: string) => { setAccountMenu(false); setPage(p); setCustomer(null); setMenu(false); setQuery('') };
