            {mobile && <View testID="bottomnav" style={{ position: 'absolute', bottom: Math.max(8, insets.bottom), left: 0, right: 0, backgroundColor: C.surface, borderTopWidth: 1, borderColor: C.line, paddingTop: 12, paddingBottom: dock.bottomPadding, flexDirection: 'row', justifyContent: 'space-around' }}>{[navs[0], navs[1], ['Capture', 'Plus'], navs[3]].map(([n, ic]) => <Pressable key={n} accessibilityRole="button" onPress={() => n === 'Capture' ? setModal({ type: data.customers.length ? 'meeting' : 'customer' }) : go(n)} style={{ alignItems: 'center', justifyContent: 'center', gap: 4, minHeight: 48, minWidth: 64 }}><Icon name={ic} color={page === n || n === 'Capture' ? C.green : C.muted} size={21} /><T style={{ fontSize: 10, color: page === n ? C.green : C.muted }}>{n === 'Action tracker' ? 'Actions' : n}</T></Pressable>)}</View>}
